/**
 * The guard hook (PreToolUse Write|Edit): the upstream-first boundary that
 * refuses a consumer brand's edit to a generated file or a shadow copy of a
 * framework file.
 * Run: node --test scripts/agent-plugins-guard.test.js
 */
const defineCases = require('@omega.js/devkit/test/define-cases');
const { execFileSync, spawnSync } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');

const { ROOT, readJson, project, brand, monorepo } = require('./agent-plugins-fixtures');

const GUARD_HOOK = path.join(ROOT, 'agent-plugins', 'claude', 'hooks', 'guard', 'run.sh');

// An Edit payload carries no content; a Write carries what is about to land —
// which is the only thing a brand-new shadow path can be judged on.
const guard = (filePath, { content, env } = {}) => spawnSync(GUARD_HOOK, {
  input: JSON.stringify({
    hook_event_name: 'PreToolUse',
    tool_name: content === undefined ? 'Edit' : 'Write',
    tool_input: content === undefined
      ? { file_path: filePath }
      : { file_path: filePath, content },
  }),
  encoding: 'utf8',
  env: { ...process.env, ...(env || {}) },
});

// The LIVE install the shadow lookup reads: node_modules/@omega.js/<framework>,
// exactly where a real brand keeps it.
const install = (dir, framework, files) => {
  for (const [rel, body] of Object.entries(files)) {
    const file = path.join(dir, 'node_modules', '@omega.js', framework, rel);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, body);
  }
};

const write = (dir, rel, body) => {
  const file = path.join(dir, rel);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, body);
  return file;
};

const guardBrand = () => {
  const dir = brand({
    targets: {
      web: { name: 'a-brand-web', dependencies: { '@omega.js/web': '^1.0.0' } },
      backend: { name: 'a-brand-backend', dependencies: { '@omega.js/backend': '^1.0.0' } },
    },
  });
  // The REAL shapes, names and all: the guard is only as honest as the tree it
  // reads, and every one of these paths exists in the shipped packages.
  install(dir, 'web', {
    'core/_layouts/blueprint/index.html': '<html></html>\n',
    'core/_includes/core/head.html': '<head></head>\n',
    'core/css/main.scss': '// core\n',
    'core/css/pages/404/index.scss': '// the 404 page sheet\n',
    'core/js/main.js': '// core main\n',
    'core/js/pages/blog.js': '// a page module, not a shadow\n',
    'themes/classy/_includes/marketing/nav.html': '<nav></nav>\n',
    'themes/classy/css/base/_type.scss': '// type\n',
    'themes/base/_sections/marketing/hero/section.html': '<section></section>\n',
    'defaults/pages/index.md': '# home\n',
    'defaults/pages/about.md': '# about\n',
    'defaults/pages/pricing.md': '# pricing\n',
    'defaults/pages/contact.md': '# contact\n',
  });
  install(dir, 'backend', {
    'templates/firestore.framework.rules': '// the framework half\n',
    'templates/firestore.rules': '// the seed a brand owns after setup\n',
    'dist/omega/routes/general/email/post.js': 'module.exports = {};\n',
    'dist/omega/schemas/general/email/post.js': 'module.exports = {};\n',
    'dist/omega/index.js': '// the Omega class\n',
    'dist/omega/libraries/email/index.js': '// framework internals\n',
  });
  return dir;
};

module.exports = defineCases({
  type: 'group',
  description: 'agent-plugins-guard',
  tests: [
    {
      name: 'guard: generated and vendored files are refused outright',
      run: (ctx) => {
        const dir = guardBrand();
        const cases = [
          ['node_modules/@omega.js/web/core/_includes/core/head.html', /node_modules/],
          ['targets/web/dist/index.html', /dist/],
          ['targets/backend/database.rules.json', /omega\.json5|setup/],
        ];
        for (const [rel, names] of cases) {
          const result = guard(path.join(dir, rel));
          ctx.expect(result.status, `${rel} was let through`).toBe(2);
          ctx.expect(result.stderr, `${rel} refusal lacks the hook name`).toMatch(/omega:guard/);
          ctx.expect(result.stderr, `${rel} refusal does not name the real source to edit`).toMatch(names);
        }
        fs.rmSync(dir, { recursive: true, force: true });
      },
    },

    {
      name: 'guard: a generated header refuses the whole file',
      run: (ctx) => {
        const dir = guardBrand();
        const marked = write(dir, 'targets/web/src/generated.html',
          '<!-- GENERATED FILE — DO NOT EDIT -->\n<p>x</p>\n');
        const banner = write(dir, 'targets/web/src/banner.html',
          '<!-- Generated by @omega.js/web -->\n<p>x</p>\n');

        for (const file of [marked, banner]) {
          const result = guard(file);
          ctx.expect(result.status, `${file} was let through`).toBe(2);
          ctx.expect(result.stderr).toMatch(/omega:guard/);
        }
        fs.rmSync(dir, { recursive: true, force: true });
      },
    },

    {
      name: 'guard: a shadow copy is refused and names the framework file it mirrors',
      run: (ctx) => {
        const dir = guardBrand();
        // One row per real override-layer root — the MECHANISM lanes only.
        const table = [
          ['targets/web/src/_layouts/blueprint/index.html', '@omega.js/web/core/_layouts/blueprint/index.html'],
          ['targets/web/src/_includes/core/head.html', '@omega.js/web/core/_includes/core/head.html'],
          ['targets/web/src/_includes/marketing/nav.html', '@omega.js/web/themes/classy/_includes/marketing/nav.html'],
          ['targets/web/src/_sections/marketing/hero/section.html', '@omega.js/web/themes/base/_sections/marketing/hero/section.html'],
          ['targets/web/src/assets/css/pages/404/index.scss', '@omega.js/web/core/css/pages/404/index.scss'],
          ['targets/web/src/assets/css/base/_type.scss', '@omega.js/web/themes/classy/css/base/_type.scss'],
          ['targets/backend/firestore.framework.rules', '@omega.js/backend/templates/firestore.framework.rules'],
          ['targets/backend/src/routes/general/email/post.js', '@omega.js/backend/dist/omega/routes/general/email/post.js'],
          ['targets/backend/src/schemas/general/email/post.js', '@omega.js/backend/dist/omega/schemas/general/email/post.js'],
        ];

        for (const [rel, mirrored] of table) {
          write(dir, rel, 'a hand-written copy\n');
          const result = guard(path.join(dir, rel));
          ctx.expect(result.status, `${rel} was let through`).toBe(2);
          ctx.expect(result.stderr).toMatch(/omega:guard/);
          ctx.expect(result.stderr.includes(mirrored), `${rel} refusal does not name ${mirrored}`).toBeTruthy();
          ctx.expect(result.stderr, `${rel} refusal does not say to file a framework issue`).toMatch(/upstream-first/);
          ctx.expect(result.stderr, `${rel} refusal does not name the marker`).toMatch(/omega:consumer-override:/);
        }
        fs.rmSync(dir, { recursive: true, force: true });
      },
    },

    {
      name: 'guard: content is never guarded — a brand page named like a default is its own',
      run: (ctx) => {
        const dir = guardBrand();
        // src/pages/ is the DESIGNED place for a brand's own copy: every page the
        // framework ships a default for is a page a brand is expected to write.
        for (const name of ['index.md', 'about.md', 'pricing.md', 'contact.md']) {
          const rel = `targets/web/src/pages/${name}`;
          ctx.expect(guard(write(dir, rel, '# our own page\n')).status, `${rel} was refused`).toBe(0);
          ctx.expect(guard(path.join(dir, rel), { content: '# a fresh page\n' }).status, `a new ${rel} was refused`).toBe(0);
        }
        fs.rmSync(dir, { recursive: true, force: true });
      },
    },

    {
      name: 'guard: the documented consumer entry files are free, and a union lane is not a shadow',
      run: (ctx) => {
        const dir = guardBrand();
        const free = [
          // theming.md tier 1 / the web guide's REPLACE-with-extend lane
          'targets/web/src/assets/css/main.scss',
          'targets/web/src/assets/js/main.js',
          // page and layout modules are a UNION: every layer's file runs
          'targets/web/src/assets/js/pages/blog.js',
          // not a layer root at all
          'targets/web/src/js/main.js',
          // the brand's authored Cloud Functions entry
          'targets/backend/src/index.js',
        ];
        for (const rel of free) {
          ctx.expect(guard(write(dir, rel, 'brand content\n')).status, `${rel} was refused`).toBe(0);
        }
        fs.rmSync(dir, { recursive: true, force: true });
      },
    },

    {
      name: 'guard: the marker in the first five lines passes the same file',
      run: (ctx) => {
        const dir = guardBrand();
        const rel = 'targets/web/src/_includes/core/head.html';
        ctx.expect(guard(write(dir, rel, 'a hand-written copy\n')).status, 'the shadow was not refused to begin with').toBe(2);

        write(dir, rel, '<!-- omega:consumer-override: this brand ships its own head -->\n<head></head>\n');
        ctx.expect(guard(path.join(dir, rel)).status, 'the marker did not let the edit through').toBe(0);

        // Below the first five lines it is a comment, not a marker.
        write(dir, rel, '1\n2\n3\n4\n5\n// omega:consumer-override: too late\n');
        ctx.expect(guard(path.join(dir, rel)).status, 'a marker on line six counted').toBe(2);
        fs.rmSync(dir, { recursive: true, force: true });
      },
    },

    {
      name: 'guard: a NEW shadow path is judged on the content being written',
      run: (ctx) => {
        const dir = guardBrand();
        const file = path.join(dir, 'targets', 'web', 'src', '_includes', 'core', 'head.html');

        const refused = guard(file, { content: '<head></head>\n' });
        ctx.expect(refused.status, 'a brand-new shadow include was let through').toBe(2);
        ctx.expect(refused.stderr.includes('@omega.js/web/core/_includes/core/head.html')).toBeTruthy();

        const allowed = guard(file, { content: '{% comment %}\n  omega:consumer-override: materialized by omega customize _includes/core/head.html\n{% endcomment %}\n' });
        ctx.expect(allowed.status, 'the marker in the written content did not let it through').toBe(0);
        fs.rmSync(dir, { recursive: true, force: true });
      },
    },

    {
      name: 'guard: OMEGA_CONSUMER_OVERRIDE=1 skips class 2 and never class 1',
      run: (ctx) => {
        const dir = guardBrand();
        const env = { OMEGA_CONSUMER_OVERRIDE: '1' };
        const shadow = write(dir, 'targets/web/src/_includes/core/head.html', 'a hand-written copy\n');
        ctx.expect(guard(shadow, { env }).status, 'the env flag did not skip the shadow check').toBe(0);

        for (const rel of ['node_modules/@omega.js/web/core/css/main.scss', 'targets/web/dist/index.html', 'targets/backend/database.rules.json']) {
          ctx.expect(guard(path.join(dir, rel), { env }).status, `${rel} escaped through the env flag`).toBe(2);
        }
        fs.rmSync(dir, { recursive: true, force: true });
      },
    },

    {
      name: 'case 15: a brand whose installed framework lacks the layout the guard reads is let through',
      run: (ctx) => {
        // An older OMEGA: the packages are installed, but with none of the core/,
        // themes/, templates/ or dist/omega/ trees the shadow lookup reads.
        const dir = brand({
          targets: {
            web: { name: 'old-web', dependencies: { '@omega.js/web': '^0.1.0' } },
            backend: { name: 'old-backend', dependencies: { '@omega.js/backend': '^0.1.0' } },
          },
        });
        install(dir, 'web', { 'package.json': '{ "name": "@omega.js/web", "version": "0.1.0" }\n', 'src/index.js': '// an older shape\n' });
        install(dir, 'backend', { 'package.json': '{ "name": "@omega.js/backend", "version": "0.1.0" }\n', 'src/index.js': '// an older shape\n' });

        for (const rel of [
          'targets/web/src/_includes/core/head.html',
          'targets/web/src/_layouts/blueprint/index.html',
          'targets/web/src/assets/css/base/_type.scss',
          'targets/backend/firestore.framework.rules',
          'targets/backend/src/routes/general/email/post.js',
        ]) {
          const result = guard(write(dir, rel, 'a hand-written file\n'));
          ctx.expect(result.status, `${rel} was refused on a layout the guard cannot read: ${result.stderr}`).toBe(0);
        }

        // No install at all reads the same: nothing to mirror, nothing refused
        fs.rmSync(path.join(dir, 'node_modules'), { recursive: true, force: true });
        ctx.expect(guard(path.join(dir, 'targets/web/src/_includes/core/head.html')).status).toBe(0);
        fs.rmSync(dir, { recursive: true, force: true });
      },
    },

    {
      name: 'guard: plain brand files and the brand\'s own rules source are free',
      run: (ctx) => {
        const dir = guardBrand();
        const free = [
          'targets/web/src/assets/css/brand.scss',
          'targets/backend/src/routes/checkout/post.js',
          'targets/backend/firestore.rules',
          'targets/backend/storage.rules',
          'targets/backend/firebase.json',
          'README.md',
          'config/omega.json5',
        ];
        for (const rel of free) {
          ctx.expect(guard(write(dir, rel, 'brand content\n')).status, `${rel} was refused`).toBe(0);
        }
        fs.rmSync(dir, { recursive: true, force: true });
      },
    },

    {
      name: 'guard: the monorepo itself is never guarded',
      run: (ctx) => {
        const dir = monorepo();
        install(dir, 'web', { 'core/_includes/core/head.html': '<head></head>\n' });
        fs.mkdirSync(path.join(dir, 'brands', 'playground', 'config'), { recursive: true });
        fs.writeFileSync(path.join(dir, 'brands', 'playground', 'config', 'omega.json5'), "{\n  targets: {\n    web: { type: 'web' },\n  },\n}\n");
        write(dir, 'brands/playground/targets/web/package.json', JSON.stringify({ name: 'p', dependencies: { '@omega.js/web': '^1.0.0' } }));
        install(path.join(dir, 'brands', 'playground'), 'web', { 'core/_includes/core/head.html': '<head></head>\n' });

        for (const rel of [
          'brands/playground/targets/web/src/_includes/core/head.html',
          'packages/web/dist/index.js',
          'packages/web/core/_includes/core/head.html',
        ]) {
          ctx.expect(guard(write(dir, rel, 'crew content\n')).status, `${rel} was guarded inside the monorepo`).toBe(0);
        }
        fs.rmSync(dir, { recursive: true, force: true });
      },
    },

    {
      name: 'guard: a project that is not a brand, and a missing jq, fail open',
      run: (ctx) => {
        const plain = project({ name: 'somebody-else', dependencies: { react: '^19.0.0' } });
        ctx.expect(guard(write(plain, 'node_modules/react/index.js', 'x\n')).status).toBe(0);
        fs.rmSync(plain, { recursive: true, force: true });

        const nothing = fs.mkdtempSync(path.join(os.tmpdir(), 'omega-guard-bare-'));
        fs.mkdirSync(path.join(nothing, '.git'));
        ctx.expect(guard(path.join(nothing, 'dist', 'index.js')).status, 'a directory with no manifest was guarded').toBe(0);
        fs.rmSync(nothing, { recursive: true, force: true });

        // No jq: a PATH carrying every other tool the script uses, and not that one.
        const bin = fs.mkdtempSync(path.join(os.tmpdir(), 'omega-guard-bin-'));
        for (const tool of ['env', 'bash', 'cat', 'dirname', 'basename', 'head', 'grep']) {
          const real = execFileSync('command', ['-v', tool], { shell: '/bin/bash', encoding: 'utf8' }).trim();
          fs.symlinkSync(real, path.join(bin, tool));
        }
        const dir = guardBrand();
        const jqless = guard(path.join(dir, 'targets', 'web', 'dist', 'index.html'), { env: { PATH: bin } });
        ctx.expect(jqless.status, `no jq did not fail open: ${jqless.stderr}`).toBe(0);
        fs.rmSync(bin, { recursive: true, force: true });
        fs.rmSync(dir, { recursive: true, force: true });
      },
    },

    {
      name: 'guard: a relative file_path fails open instead of walking forever',
      run: (ctx) => {
        // No .git anywhere up the tree, which is what exposes the loop: a walk that
        // only stops at a git root never stops when `dirname` bottoms out at ".".
        const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'omega-guard-rel-'));
        fs.writeFileSync(path.join(dir, 'package.json'), JSON.stringify({ name: 'a-brand', dependencies: { '@omega.js/manager': '^1.0.0' } }));
        // `dirname` of a relative path bottoms out at "." and stays there, so an
        // unanchored walk never terminates. Both walks refuse a non-absolute dir.
        const result = spawnSync('timeout', ['10', GUARD_HOOK], {
          input: JSON.stringify({
            hook_event_name: 'PreToolUse',
            tool_name: 'Edit',
            tool_input: { file_path: 'targets/web/src/_includes/core/head.html' },
          }),
          cwd: dir,
          encoding: 'utf8',
        });
        ctx.expect(result.status, 'the hook spun forever on a relative path').not.toBe(124);
        ctx.expect(result.status, `a relative path did not fail open: ${result.stderr}`).toBe(0);
        fs.rmSync(dir, { recursive: true, force: true });
      },
    },

    {
      name: 'guard: hooks.json wires the guard as a third PreToolUse Write|Edit command',
      run: (ctx) => {
        const hooks = readJson(path.join(ROOT, 'agent-plugins', 'claude', 'hooks', 'hooks.json')).hooks;
        const entry = hooks.PreToolUse.find((h) => h.matcher === 'Write|Edit');
        ctx.expect(entry, 'no PreToolUse Write|Edit entry').toBeTruthy();
        const commands = entry.hooks.map((hook) => hook.command);
        ctx.expect(commands.some((command) => /hooks\/guard\/run\.sh/.test(command)), 'the guard is not registered').toBeTruthy();
      },
    },
  ],
});
